export function iniciais(nomeCompleto) {
  if (typeof nomeCompleto !== 'string') throw new TypeError('nome deve ser texto');
  const partes = nomeCompleto.trim().split(' ').filter(Boolean);
  if (partes.length === 0) return '';
  const primeira = partes[0].charAt(0).toUpperCase();
  const ultima = partes.length > 1 ? partes[partes.length - 1].charAt(0).toUpperCase() : '';
  return primeira + ultima;
}

