function instante(texto) {
  const ms = Date.parse(texto);
  if (Number.isNaN(ms)) throw new RangeError('data inválida: ' + texto);
  return ms;
}

export function estaVigente(inicioIso, fimIso, agoraIso) {
  const inicio = instante(inicioIso);
  const fim = instante(fimIso);
  const agora = instante(agoraIso);
  if (fim <= inicio) throw new RangeError('fim deve ser posterior ao início');
  return inicio <= agora && agora < fim;
}

export function diaDoPeriodo(iso) {
  return new Date(instante(iso)).toISOString().slice(0, 10);
}

