export async function primeirosItens(fonte, n) {
  if (!Number.isInteger(n) || n < 0) throw new RangeError('n deve ser inteiro não negativo');
  const resultado = [];
  if (n === 0) return resultado;
  for await (const item of fonte) {
    resultado.push(item);
    if (resultado.length === n) break;
  }
  return resultado;
}

