    const estado = { produzidos: 0, finalizada: false };
    async function* fonte() {
      try {
        for (let i = 1; i <= 100; i++) {
          estado.produzidos++;
          yield i;
        }
      } finally {
        estado.finalizada = true;
      }
    }
    expect(await primeirosItens(fonte(), 3)).toEqual([1, 2, 3]);
    expect(estado.produzidos).toBe(3);
    expect(estado.finalizada).toBe(true);
  });
  test('n inválido rejeita com RangeError', async () => {
    await expect(primeirosItens([1], -1)).rejects.toThrow(RangeError);
  });
});

