import { itensDePaginas } from './main.js';

async function coletar(iteravel) {
  const itens = [];
  for await (const item of iteravel) itens.push(item);
  return itens;
}

function paginasFalsas(paginas, chamadas) {
  return async pagina => {
    chamadas.push(pagina);
    return paginas[pagina - 1] || [];
  };
}

describe('itensDePaginas', () => {
  test('produz os itens de todas as páginas em ordem', async () => {
    const busca = paginasFalsas([[1, 2], [3]], []);
    expect(await coletar(itensDePaginas(busca))).toEqual([1, 2, 3]);
  });
  test('uma página vazia encerra a sequência', async () => {
    const chamadas = [];
    const busca = paginasFalsas([['a'], []], chamadas);
    expect(await coletar(itensDePaginas(busca))).toEqual(['a']);
    expect(chamadas).toEqual([1, 2]);
  });
  test('só busca a página seguinte quando o consumidor avança', async () => {
    const chamadas = [];
    const busca = paginasFalsas([[1, 2], [3]], chamadas);
    for await (const item of itensDePaginas(busca)) {
      if (item === 1) break;
    }
    expect(chamadas).toEqual([1]);
