export async function* itensDePaginas(buscarPagina) {
  const todos = [];
  for (let pagina = 1; ; pagina++) {
    const itens = await buscarPagina(pagina);
    if (itens.length === 0) break;
    todos.push(...itens);
  }
  for (const item of todos) yield item;
}

export async function* itensDePaginas(buscarPagina) {
  for (let pagina = 1; ; pagina++) {
    let itens;
    try {
      itens = await buscarPagina(pagina);
    } catch {
      return;
    }
    if (itens.length === 0) return;
    for (const item of itens) yield item;
  }
}

