import { carregarPerfil } from './main.js';

async function capturarErro(promessa) {
  try {
    await promessa;
  } catch (erro) {
    return erro;
  }
  return undefined;
}

describe('carregarPerfil', () => {
  test('sucesso devolve o valor de buscar', async () => {
    expect(await carregarPerfil(async () => ({ nome: 'Ana' }))).toEqual({ nome: 'Ana' });
  });
  test('falha vira Error com a mensagem pública', async () => {
    const original = new Error('timeout no banco');
    const erro = await capturarErro(carregarPerfil(async () => { throw original; }));
    expect(erro instanceof Error).toBe(true);
    expect(erro.message).toBe('Perfil indisponível');
  });
  test('o erro original é preservado em cause, sem alteração', async () => {
    const original = new Error('timeout no banco');
    const erro = await capturarErro(carregarPerfil(async () => { throw original; }));
    expect(erro.cause).toBe(original);
  });
  test('causa que não é Error chega como foi recebida', async () => {
    const erro = await capturarErro(carregarPerfil(async () => { throw 'falha de rede'; }));
    expect(erro.cause).toBe('falha de rede');
  });
});

